;(function( $, window, document, undefined ) {
    'use strict';
    var code_themes = [];
    function initializeCodeMirror() {
        // Initialize CodeMirror for each found textarea
        $('.codemirror_editor').each( function() {

            if ( typeof CodeMirror !== 'function' ) { return; }

            var $this   = $(this),
            $textarea   = $this.find('textarea'),
            $inited     = $this.find('.CodeMirror'),
            data_editor = $textarea.data('editor');

            if ( $inited.length ) {
                $inited.remove();
            }

            var interval = setInterval(function () {
                if ( $this.is(':visible') ) {
                    var editor = CodeMirror.fromTextArea( $textarea[0], data_editor );

                    // load code-mirror theme css.
                    if ( data_editor.theme !== 'default' && code_themes.indexOf(data_editor.theme) === -1 ) {

                        var $cssLink = $('<link>');

                        $('#codemirror-css').after( $cssLink );

                        $cssLink.attr({
                          rel: 'stylesheet',
                          id: 'stcode-codemirror-'+ data_editor.theme +'-css',
                          href: data_editor.cdnURL +'/theme/'+ data_editor.theme +'.min.css',
                          type: 'text/css',
                          media: 'all'
                        });

                        code_themes.push(data_editor.theme);

                    }

                    CodeMirror.modeURL = data_editor.cdnURL +'/mode/%N/%N.min.js';
                    CodeMirror.autoLoadMode(editor, data_editor.mode);

                    editor.on( 'change', function( editor, event ) {
                        $textarea.val( editor.getValue() ).trigger('change');
                    });

                    clearInterval(interval);
                }
            });
        });
    }

    $(document).ready( function() {
        initializeCodeMirror();
        $('[data-toggle="tooltip"]').tooltip();
        // Adiciona um evento de clique a todos os elementos <li>
        document.querySelectorAll('.dots_tags li').forEach(function(li) {
            li.addEventListener('click', function() {
                // Cria um elemento de texto temporário
                var tempTextArea = document.createElement('textarea');
                // Define o valor do texto como o conteúdo do <li> clicado
                tempTextArea.value = this.innerText;
                // Adiciona o elemento de texto temporário ao corpo do documento
                document.body.appendChild(tempTextArea);
                // Seleciona e copia o texto
                tempTextArea.select();
                document.execCommand('copy');
                // Remove o elemento de texto temporário
                document.body.removeChild(tempTextArea);
            });
        });
    });
})( jQuery, window, document );